// Real artefacts, bundled at build time: the untouched 1978-style F77 source,
// the spec generated by orchestrator/f77_analyzer.py, and the run log written by
// orchestrator/graph.py.
import fortranSource from "../../targets/bioumat/SUBROUTINES.FOR?raw";
import specJson from "../../orchestrator/out/spec.json";
import runLogJson from "../../orchestrator/out/run_log.json";
import type { RunLog, Spec } from "./types";

export const SOURCE_LINES: string[] = fortranSource.replace(/\r\n/g, "\n").replace(/\n$/, "").split("\n");
export const SPEC = specJson as unknown as Spec;
export const RUN_LOG = runLogJson as unknown as RunLog;
export const GITHUB_REPO = "hvmathan/necrofort";
